-- 6. Seed text (#11 North)
UPDATE course_seeds SET target_text = 'ches i ddim amser, er bo’ fi isio gweld chdi', last_edit_event_id = :'ev_n' WHERE course_code = 'cym_nv2_for_eng' AND seed_number = 1178 AND target_text = 'ges i ddim amser, er bo’ fi isio gweld chdi';

-- 7. Display caches that name a touched LEGO are cleared (runtime fallback rebuilds them)
UPDATE course_practice_phrases p SET decomposition = NULL, decomposition_course_version = NULL, display_tiling = NULL, display_tiling_version = NULL
WHERE (p.course_code, p.seed_number) IN (SELECT course_code, seed_number FROM t_seeds) AND (p.decomposition IS NOT NULL OR p.display_tiling IS NOT NULL);
UPDATE course_practice_phrases p SET decomposition = NULL, decomposition_course_version = NULL, display_tiling = NULL, display_tiling_version = NULL
WHERE p.id IN (SELECT id FROM t_extra) AND (p.decomposition IS NOT NULL OR p.display_tiling IS NOT NULL);

-- 8. Flags: unflag, note, follow a moved LEGO
UPDATE lego_proof_flags f SET lego_id = t.new_id, flagged = false, updated_at = now(),
  note = left(CASE t.kind WHEN 'fixed' THEN 'fixed (job #554·P)' ELSE 'no change: already taught (Aran 2026-10-13)' END || ' — ' || coalesce(f.note, ''), 1000)
FROM t_flags t WHERE t.course_code = f.course_code AND t.old_id = f.lego_id;

-- CHECKS
CREATE TEMP TABLE post AS SELECT * FROM pg_temp.fp();
SELECT 'CHANGED (before)' k, * FROM (SELECT * FROM pre EXCEPT SELECT * FROM post) d UNION ALL SELECT 'CHANGED (after)', * FROM (SELECT * FROM post EXCEPT SELECT * FROM pre) d2;
DO $$
DECLARE n_text int; n_set int; n_move int; n_seed int;
BEGIN
  IF EXISTS (SELECT * FROM pre EXCEPT SELECT * FROM post) OR EXISTS (SELECT * FROM post EXCEPT SELECT * FROM pre) THEN
    RAISE EXCEPTION 'CHECK FAILED: something outside the touched sandbox seeds changed'; END IF;
  SELECT count(*) INTO n_text FROM course_practice_phrases WHERE last_edit_event_id IN ((SELECT ev_n FROM ev), (SELECT ev_s FROM ev)) AND id IN ('cym_nv2_for_eng:S1009L01C01','cym_nv2_for_eng:S1009L01C03','cym_nv2_for_eng:S1009L01B01','cym_nv2_for_eng:S1010L04C01','cym_nv2_for_eng:S1010L04C03','cym_nv2_for_eng:S1010L04C04','cym_sv2_for_eng:S1010L04C01','cym_sv2_for_eng:S1010L04C03','cym_sv2_for_eng:S1010L04C04','cym_nv2_for_eng:S1092L02C01','cym_nv2_for_eng:S1092L02B01','cym_sv2_for_eng:S1092L02B01','cym_nv2_for_eng:S1115L02C01','cym_nv2_for_eng:S1115L02B01','cym_nv2_for_eng:S1161L03C01','cym_sv2_for_eng:S1161L03B01','cym_nv2_for_eng:S1178L01C01','cym_nv2_for_eng:S1178L01B01','cym_nv2_for_eng:S1178L01B02','cym_nv2_for_eng:S1178L01B03','cym_nv2_for_eng:S1178L01B04','cym_nv2_for_eng:S1178L01U01','cym_nv2_for_eng:S1178L01U02','cym_nv2_for_eng:S1178L01U03','cym_nv2_for_eng:S1178L01U04','cym_nv2_for_eng:S1178L01U05','cym_nv2_for_eng:S1178L01U06','cym_nv2_for_eng:S1178L02B04','cym_nv2_for_eng:S1178L02U01','cym_nv2_for_eng:S1335L04U03','cym_sv2_for_eng:S1152L02B01','cym_sv2_for_eng:S1152L02B02','cym_sv2_for_eng:S1152L02B03','cym_sv2_for_eng:S1152L02B04','cym_sv2_for_eng:S1152L02U01','cym_sv2_for_eng:S1152L02U02','cym_sv2_for_eng:S1152L02U03','cym_sv2_for_eng:S1152L02U04','cym_sv2_for_eng:S1152L02U05','cym_sv2_for_eng:S1152L02U06','cym_sv2_for_eng:S1152L02U07','cym_sv2_for_eng:S1152L02U08','cym_sv2_for_eng:S1257L02B01','cym_sv2_for_eng:S1257L02B02','cym_sv2_for_eng:S1257L02B03','cym_sv2_for_eng:S1257L02B04','cym_sv2_for_eng:S1257L02U01','cym_sv2_for_eng:S1257L02U02','cym_sv2_for_eng:S1257L02U03','cym_sv2_for_eng:S1257L02U04','cym_sv2_for_eng:S1257L02U05','cym_sv2_for_eng:S1257L02U06','cym_sv2_for_eng:S1268L02B02','cym_sv2_for_eng:S1364L03B01','cym_sv2_for_eng:S1364L03B02','cym_sv2_for_eng:S1364L03B03','cym_sv2_for_eng:S1364L03B04','cym_sv2_for_eng:S1364L03U01','cym_sv2_for_eng:S1364L03U02','cym_sv2_for_eng:S1364L03U03','cym_sv2_for_eng:S1364L03U04','cym_sv2_for_eng:S1364L03U05','cym_sv2_for_eng:S1364L03U06','cym_sv2_for_eng:S1434L02B01','cym_sv2_for_eng:S1590L02B01','cym_sv2_for_eng:S1590L02B02','cym_sv2_for_eng:S1590L02B03','cym_sv2_for_eng:S1590L02B04','cym_sv2_for_eng:S1590L02U01','cym_sv2_for_eng:S1590L02U02','cym_sv2_for_eng:S1590L02U03','cym_sv2_for_eng:S1590L02U04','cym_sv2_for_eng:S1590L02U05','cym_sv2_for_eng:S1590L02U06','cym_nv2_for_eng:S1184L01U04','cym_nv2_for_eng:S1184L03U01','cym_nv2_for_eng:S1184L03U07','cym_nv2_for_eng:S1185L03B04','cym_nv2_for_eng:S1185L03U01','cym_nv2_for_eng:S1191L01U04','cym_nv2_for_eng:S1331L02U02','cym_nv2_for_eng:S1362L01U01','cym_nv2_for_eng:S1371L02B03','cym_nv2_for_eng:S1376L01U01','cym_nv2_for_eng:S1386L01U05','cym_nv2_for_eng:S1402L01U02','cym_nv2_for_eng:S1454L01U02');
  IF n_text <> 87 THEN RAISE EXCEPTION 'CHECK FAILED: % of 87 phrase texts written', n_text; END IF;
  SELECT count(*) INTO n_set FROM course_legos WHERE last_edit_event_id IN ((SELECT ev_n FROM ev), (SELECT ev_s FROM ev));
  IF n_set <> 65 THEN RAISE EXCEPTION 'CHECK FAILED: % LEGOs stamped', n_set; END IF;
  SELECT count(*) INTO n_seed FROM course_seeds WHERE last_edit_event_id = (SELECT ev_n FROM ev) AND target_text = 'ches i ddim amser, er bo’ fi isio gweld chdi';
  IF n_seed <> 1 THEN RAISE EXCEPTION 'CHECK FAILED: seed text not written'; END IF;
  IF EXISTS (SELECT 1 FROM course_practice_phrases p JOIN t_seeds USING (course_code, seed_number) WHERE p.target_text ~ 'newydd ddechrau' AND p.last_edit_event_id IN ((SELECT ev_n FROM ev), (SELECT ev_s FROM ev))) THEN
    RAISE EXCEPTION 'CHECK FAILED: wrote a dw i newydd ddechrau phrase'; END IF;
  IF (SELECT count(*) FROM lego_proof_flags f JOIN t_flags t ON t.course_code=f.course_code AND t.new_id=f.lego_id WHERE NOT f.flagged) <> (SELECT count(*) FROM t_flags) THEN
    RAISE EXCEPTION 'CHECK FAILED: flags'; END IF;
  -- every phrase of a touched seed still sits under a LEGO (FK) and no is_new LEGO there lost its practice (debut guard fires at COMMIT)
  RAISE NOTICE 'ALL CHECKS PASSED';
END $$;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT l.course_code, l.lego_id, l.is_new, l.target_text, l.known_text,
  (SELECT count(*) FROM course_practice_phrases p WHERE p.course_code=l.course_code AND p.seed_number=l.seed_number AND p.lego_index=l.lego_index) phrases
FROM course_legos l JOIN t_seeds USING (course_code, seed_number) ORDER BY 1, 2;
SELECT 'finishing with' k, :'finish' v;
:finish;
SELECT :'finish' = 'COMMIT' AS do_refresh \gset
\if :do_refresh
REFRESH MATERIALIZED VIEW CONCURRENTLY course_round_index;
\endif
